import java.io.*;
import java.math.BigInteger;
import java.util.ArrayDeque;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        String first = fs.next();
        if (first == null || first.isEmpty()) return;

        int rows = Integer.parseInt(first);
        int cols = Integer.parseInt(fs.next());
        int equations = rows + cols;
        int variables = 26 * 26;

        int[][] coefficient = new int[equations][variables];
        BigInteger[] residual = new BigInteger[equations];
        boolean[] appears = new boolean[variables];

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                String name = fs.next();
                int v = (name.charAt(0) - 'a') * 26 + name.charAt(1) - 'a';
                coefficient[r][v]++;
                coefficient[rows + c][v]++;
                appears[v] = true;
            }
            residual[r] = new BigInteger(fs.next());
        }

        for (int c = 0; c < cols; c++) {
            residual[rows + c] = new BigInteger(fs.next());
        }

        int[] unknownCount = new int[equations];
        ArrayDeque<Integer> queue = new ArrayDeque<>();

        for (int e = 0; e < equations; e++) {
            for (int v = 0; v < variables; v++) {
                if (coefficient[e][v] > 0) unknownCount[e]++;
            }
            if (unknownCount[e] == 1) queue.add(e);
        }

        boolean[] known = new boolean[variables];
        BigInteger[] value = new BigInteger[variables];

        while (!queue.isEmpty()) {
            int e = queue.poll();
            if (unknownCount[e] != 1) continue;

            int v = -1;
            for (int i = 0; i < variables; i++) {
                if (coefficient[e][i] > 0 && !known[i]) {
                    v = i;
                    break;
                }
            }
            if (v == -1) continue;

            BigInteger divisor = BigInteger.valueOf(coefficient[e][v]);
            value[v] = residual[e].divide(divisor);
            known[v] = true;

            for (int other = 0; other < equations; other++) {
                int count = coefficient[other][v];
                if (count == 0) continue;

                residual[other] = residual[other].subtract(
                    value[v].multiply(BigInteger.valueOf(count))
                );
                unknownCount[other]--;
                if (unknownCount[other] == 1) queue.add(other);
            }
        }

        StringBuilder out = new StringBuilder();
        for (int v = 0; v < variables; v++) {
            if (appears[v]) {
                out.append((char) ('a' + v / 26))
                   .append((char) ('a' + v % 26))
                   .append(' ')
                   .append(value[v])
                   .append('\n');
            }
        }
        System.out.print(out);
    }
}
